std::string normalizeArabic(std::string_view s) {
    std::string out;
    out.reserve(s.size());
    std::size_t i = 0, n = s.size();
    while (i < n) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        std::size_t len = 1;
        if ((c & 0x80u) == 0x00u)      len = 1;
        else if ((c & 0xE0u) == 0xC0u) len = 2;
        else if ((c & 0xF0u) == 0xE0u) len = 3;
        else if ((c & 0xF8u) == 0xF0u) len = 4;
        if (i + len > n) len = 1;  // (AR) تسلسل مبتور: انسخ دفاعيًّا / truncated: copy defensively
        if (len == 2) {
            unsigned int cp = ((c & 0x1Fu) << 6) |
                              (static_cast<unsigned char>(s[i + 1]) & 0x3Fu);
            if ((cp >= 0x064Bu && cp <= 0x0652u) || cp == 0x0670u || cp == 0x0640u) {
                i += 2;  // (AR) جرّد تشكيلًا/تطويلًا / strip tashkeel/tatweel
                continue;
            }
            if (cp == 0x0623u || cp == 0x0625u || cp == 0x0622u || cp == 0x0671u) {
                out.push_back(static_cast<char>(0xD8));  // (AR) ا U+0627 / bare alef
                out.push_back(static_cast<char>(0xA7));
                i += 2;
                continue;
            }
        }
        for (std::size_t k = 0; k < len; ++k) out.push_back(s[i + k]);
        i += len;
    }
    return out;
}

const char *appletExec(std::string_view arabic) {
    for (std::size_t i = 0; i < kAppletsCount; ++i) {
        if (arabic == kApplets[i].arabic) return kApplets[i].exec;
    }
    const std::string n = normalizeArabic(arabic);
    for (std::size_t i = 0; i < kAppletsCount; ++i) {
        if (n == kApplets[i].arabicNorm) return kApplets[i].exec;
    }
    return nullptr;
}

const AppletEntry *findApplet(std::string_view arabic) {
    for (std::size_t i = 0; i < kAppletsCount; ++i) {
        if (arabic == kApplets[i].arabic) return &kApplets[i];
    }
    const std::string n = normalizeArabic(arabic);
    for (std::size_t i = 0; i < kAppletsCount; ++i) {
        if (n == kApplets[i].arabicNorm) return &kApplets[i];
    }
    return nullptr;
}

// (AR) جدول الأيّام مرتّب بترتيب tm_wday (0=الأحد) — من calendar.yaml.
// (EN) weekday table ordered by tm_wday (0=Sunday) — from calendar.yaml.
const char *const kWeekdays[] = {
    "الأحد",
    "الاثنين",
    "الثلاثاء",
    "الأربعاء",
    "الخميس",
    "الجمعة",
    "السبت",
};
const std::size_t kWeekdaysCount = sizeof(kWeekdays) / sizeof(kWeekdays[0]);

const char *weekdayName(int tmWday) {
    if (tmWday < 0 || static_cast<std::size_t>(tmWday) >= kWeekdaysCount) {
        return nullptr;
    }
    return kWeekdays[tmWday];
}

